import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    bounds = [[n + 1] * n for _ in range(n + 1)]
    for i in range(2, len(data), 3):
        l, r, x = data[i:i + 3]
        row = bounds[l - 1]
        if r < row[x - 1]:
            row[x - 1] = r

    for l in range(n - 1, -1, -1):
        row, nxt = bounds[l], bounds[l + 1]
        for k in range(l, n):
            if nxt[k] < row[k]:
                row[k] = nxt[k]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the valid count on [l,r), divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for l in range(n + 1):
        dp[l][l] = 1
    for l in range(n - 1, -1, -1):
        row = dp[l]
        bound = bounds[l]
        for r in range(l + 1, n + 1):
            total = 0
            for k in range(l, r):
                if r < bound[k]:
                    total += row[k] * dp[k + 1][r]
            row[r] = total % MOD * inv[r - l] % MOD

    ans = dp[0][n]
    for i in range(2, n + 1):
        ans = ans * i % MOD
    print(ans)


if __name__ == '__main__':
    main()

