import sys
from collections import deque
from array import array

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1
    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n
    while q:
        u = q.popleft()
        v = a[u]
        src, dst = dp[u], dp[v]
        if src is None:
            if dst is None:
                dp[v] = array('I', range(1, m + 1))
            else:
                for j in range(m):
                    dst[j] = dst[j] * (j + 1) % MOD
        else:
            s = 0
            if dst is None:
                for j in range(m):
                    s += src[j]
                    if s >= MOD:
                        s -= MOD
                    src[j] = s
                dp[v] = src
            else:
                for j in range(m):
                    s += src[j]
                    if s >= MOD:
                        s -= MOD
                    dst[j] = dst[j] * s % MOD
        dp[u] = None
        deg[v] -= 1
        if deg[v] == 0:
            q.append(v)
    ans = 1
    for start in range(n):
        if deg[start] == 0:
            continue
        acc = None
        u = start
        while deg[u]:
            deg[u] = 0
            cur = dp[u]
            if cur is not None:
                if acc is None:
                    acc = cur
                else:
                    for j in range(m):
                        acc[j] = acc[j] * cur[j] % MOD
            dp[u] = None
            u = a[u]
        ways = m if acc is None else sum(acc) % MOD
        ans = ans * ways % MOD
    print(ans)


if __name__ == '__main__':
    main()

