import sys
from math import gcd

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    factors = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            if value % p == 0:
                e = 0
                while value % p == 0:
                    value //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if value > 1:
            if value not in factors:
                factors[value] = [0] * (n - 1)
            factors[value][i] = 1

    ans = 1
    for p, exps in factors.items():
        g = 0
        for e in exps:
            g = gcd(g, e)
        if g > 1:
            p = pow(p, g, MOD)
            exps = [e // g for e in exps]
        total = sum(exps)
        powers = [1] * (total + 1)
        for h in range(total):
            powers[h + 1] = powers[h] * p % MOD

        dp = [1]
        for i, e in enumerate(exps, 1):
            size = len(dp)
            if e == 0:
                dp = [v * powers[h] % MOD for h, v in enumerate(dp)]
                continue
            nd = [0] * (size + e)
            for h, v in enumerate(dp):
                nd[h + e] = v * powers[h + e] % MOD
            zero = 0
            for h in range(min(e, size)):
                zero += dp[h] * pow(p, i * (e - h), MOD)
            nd[0] = zero % MOD
            for h in range(e, size):
                j = h - e
                nd[j] = (nd[j] + dp[h] * powers[j]) % MOD
            dp = nd
        ans = ans * (sum(dp) % MOD) % MOD
    print(ans)


if __name__ == '__main__':
    solve()

