class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        steps = [0] * (length + 1)
        for value in range(2, length + 1):
            steps[value] = 1 + steps[value.bit_count()]
        good = [value for value in range(1, length + 1) if steps[value] < k]

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % mod
        inverse = [1] * (length + 1)
        inverse[length] = pow(fact[length], mod - 2, mod)
        for i in range(length, 0, -1):
            inverse[i - 1] = inverse[i] * i % mod

        answer = 0
        prefix = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                subtotal = 0
                for weight in good:
                    needed = weight - prefix
                    if needed < 0:
                        continue
                    if needed > remaining:
                        break
                    subtotal += inverse[needed] * inverse[remaining - needed]
                answer = (answer + fact[remaining] * (subtotal % mod)) % mod
                prefix += 1
        return answer

