import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    limit = 1 << 100
    upper = limit - a[-1] - 1

    def dfs(vals, p0, p1, r, step):
        if step == limit:
            return p0
        ns = step << 1
        best = -10000
        for b in (0, 1):
            nr = r + b * step
            if nr > upper or (nr == 0 and ns > upper):
                continue
            gain = p1 if b else p0
            if not vals:
                if gain > best:
                    best = gain
                continue
            nxt = []
            q0 = q1 = 0
            for v in vals:
                v += b
                if v & 1:
                    if v & 2:
                        q0 += 1
                    else:
                        q1 += 1
                else:
                    nxt.append(v >> 1)
            score = gain + dfs(nxt, q0, q1, nr, ns)
            if score > best:
                best = score
        return best

    print(dfs(a, 0, 0, 0, 1))

if __name__ == '__main__':
    main()

