class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(2, n + 1):
            fact[i] = fact[i - 1] * i

        remaining = list(range(1, n + 1))
        odd, even = (n + 1) // 2, n // 2
        answer = []

        while remaining:
            m = len(remaining) - 1
            for i, x in enumerate(remaining):
                if answer and (answer[-1] % 2 == x % 2):
                    continue

                o = odd - (x % 2)
                e = even - (1 - x % 2)
                required_odd = (m + 1) // 2 if x % 2 == 0 else m // 2
                if o != required_odd:
                    continue

                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(x)
                    remaining.pop(i)
                    odd, even = o, e
                    break
            else:
                return []

        return answer

