from math import gcd

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        weights = [0] * m
        for i in range(m):
            j = n - 1 - i
            weights[i] = powers[i] if i == j else (powers[i] + powers[j]) % k

        # Suffix remainders are precisely the multiples of this gcd.
        # Digits 0..9 cover every residue modulo k, since k <= 9.
        suffix = [k] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])

        result = ['0'] * n
        remainder = 0
        for i, w in enumerate(weights):
            for d in range(9, 0 if i == 0 else -1, -1):
                value = remainder + d * w
                if value % suffix[i + 1] == 0:
                    result[i] = result[n - 1 - i] = str(d)
                    remainder = value % k
                    break

        return ''.join(result)

