class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        q = deque()
        right = len(nums) - 1
        cost = 0
        answer = 0
        for left in range(len(nums) - 1, -1, -1):
            value = nums[left]
            while q and nums[q[-1]] < value:
                j = q.pop()
                end = q[-1] if q else right + 1
                cost += (end - j) * (value - nums[j])
            q.append(left)
            while cost > k:
                cost -= nums[q[0]] - nums[right]
                if q[0] == right:
                    q.popleft()
                right -= 1
            answer += right - left + 1
        return answer

