        counts[pair] = min(k, counts.get(pair, 0) + 1)

    def compare(x, y):
        v = (x[0] - 1) * y[1] - (y[0] - 1) * x[1]
        return (v > 0) - (v < 0)

    pairs = sorted(counts, key=cmp_to_key(compare))
    dp = [-1] * (k + 1)
    dp[0] = 1
    seen = 0
    for a, b in pairs:
        for _ in range(counts[(a, b)]):
            seen += 1
            for j in range(min(k, seen), 0, -1):
                value = a * dp[j - 1] + b
                if value > dp[j]:
                    dp[j] = value
    print(dp[k])


