class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        answer = len(s)
        for target in range(1, max(counts) + 1):
            absent = 0
            present = 0
            previous = 0
            for count in counts:
                new_absent = min(absent, present) + count
                if count < target:
                    deficit = target - count
                    new_present = min(
                        absent + deficit - min(previous, deficit),
                        present + deficit - min(max(previous - target, 0), deficit)
                    )
                else:
                    new_present = min(absent, present) + count - target
                absent, present = new_absent, new_present
                previous = count
            answer = min(answer, absent, present)
        return answer

