import sys

MOD = 998244353


def solve(h, w, rows):
    n = h + w
    parent = list(range(n))
    size = [1] * n
    parity = [0] * n
    cols = bytearray(w)
    components = n

    for i, row in enumerate(rows):
        hp = 0
        for j, ch in enumerate(row):
            if ch == 65:
                hp ^= 1
                cols[j] ^= 1
            else:
                a = i
                x = 0
                while parent[a] != a:
                    x ^= parity[a]
                    a = parent[a]

                b = h + j
                y = 0
                while parent[b] != b:
                    y ^= parity[b]
                    b = parent[b]

                d = 1 ^ hp ^ cols[j] ^ x ^ y
                if a == b:
                    if d:
                        return 0
                else:
                    if size[a] < size[b]:
                        a, b = b, a
                    parent[b] = a
                    parity[b] = d
                    size[a] += size[b]
                    components -= 1
        if hp:
            return 0

    if any(cols):
        return 0
    return pow(2, components, MOD)


def main():
    data = sys.stdin.buffer
    t = int(data.readline())
    ans = []
    for _ in range(t):
        h, w = map(int, data.readline().split())
        rows = [data.readline().strip() for _ in range(h)]
        ans.append(str(solve(h, w, rows)))
    print('\n'.join(ans))


