        size = len(component)
        for bit in range(largest.bit_length()):
            ones = sum((values[v] >> bit) & 1 for v in component)
            if ones * 2 > size:
                mask |= 1 << bit
        if mask:
            for v in component:
                values[v] ^= mask
    print(*values)

