import sys


def solve(n, aa, bb):
    if aa == bb:
        return 0
    a = [i for i, c in enumerate(aa) if c == 49]
    b = [i for i, c in enumerate(bb) if c == 49]
    m, h = len(a), len(b)
    if m < h:
        return -1
    if h == 1:
        return max(abs(a[0] - b[0]), abs(a[-1] - b[0]))
    first, last = a[0], a[-1]

    def feasible(k):
        p = b[0] - 1 - k
        if p >= first:
            return False
        j = 0
        prev = b[0] - 1
        for z, y in enumerate(b):
            g = y - prev - 1
            if g:
                while j < m and a[j] <= p + g:
                    p = a[j] + ((a[j] - p) & 1)
                    while j < m and a[j] <= p:
                        j += 1
                if p > prev + k:
                    return False
                p += g
            if j == m:
                return False
            q = last if z == h - 1 else a[j]
            p = q + ((q - p - 1) & 1)
            if p > y + k:
                return False
            while j < m and a[j] <= p:
                j += 1
            prev = y
        return True

    lower = max(
        abs(first - b[0]),
        abs(last - b[-1]),
        (last - first - b[-1] + b[0] + 1) // 2,
    )
    if feasible(lower):
        return lower
    if feasible(lower + 1):
        return lower + 1
    answer = 2 * n + 2
    for parity in (0, 1):
        hi = (min(2 * n + 1, answer - 1) - parity) // 2
        if not feasible(2 * hi + parity):
            continue
        lo = (lower + 1 - parity) // 2
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if feasible(2 * mid + parity):
                hi = mid
            else:
                lo = mid
        answer = min(answer, 2 * hi + parity)
    return answer if answer <= 2 * n + 1 else -1


