import sys
import heapq


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, W = data[0:2]
    groups = [[] for _ in range(W + 1)]
    for i in range(2, len(data), 2):
        w, v = data[i], data[i + 1]
        if v > 1:
            groups[w].append(1 - v)

    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        gains = []
        total = 0
        for _ in range(W // w):
            if not heap or heap[0] >= 0:
                break
            x = heap[0]
            total -= x
            gains.append(total)
            heapq.heapreplace(heap, x + 2)

        ndp = dp.copy()
        for k, value in enumerate(gains, 1):
            shift = k * w
            for t in range(shift, W + 1):
                cand = dp[t - shift] + value
                if cand > ndp[t]:
                    ndp[t] = cand
        dp = ndp

    print(dp[W])


if __name__ == '__main__':
    solve()

