from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Every subtree occupies one contiguous postorder interval.
        start = [0] * n
        end = [0] * n
        text = []
        stack = [0]
        while stack:
            u = stack.pop()
            if u >= 0:
                start[u] = len(text)
                stack.append(~u)
                stack.extend(reversed(children[u]))
            else:
                u = ~u
                text.append(s[u])
                end[u] = len(text)

        # Manacher radii for odd-length and even-length palindromes.
        odd = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        answer = []
        for a, b in zip(start, end):
            length = b - a
            mid = (a + b) // 2
            if length % 2:
                answer.append(odd[mid] >= length // 2 + 1)
            else:
                answer.append(even[mid] >= length // 2)
        return answer

