from math import isqrt


def solve():
    n = int(sys.stdin.buffer.read())
    limit = isqrt(n)
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b'\x00' * ((limit - start) // p + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]
    answer = 0
    for p in primes:
        if p ** 8 > n:
            break
        answer += 1
    j = len(primes) - 1
    for i, p in enumerate(primes):
        if p * p >= limit:
            break
        while j > i and p * primes[j] > limit:
            j -= 1
        if j <= i:
            break
        answer += j - i
    print(answer)


if __name__ == '__main__':
    solve()

