class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        counts = [0] * 26
        for c in s:
            counts[ord(c) - 97] += 1
        head = 0
        for _ in range(t):
            head = (head - 1) % 26
            b = (head + 1) % 26
            counts[b] = (counts[b] + counts[head]) % mod
        return sum(counts) % mod

