import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        low = limit // 10
        prime = bytearray(b'\x01') * limit
        prime[0:2] = b'\x00\x00'
        for p in range(2, int((limit - 1) ** 0.5) + 1):
            if prime[p]:
                prime[p*p:limit:p] = b'\x00' * (((limit - 1 - p*p) // p) + 1)
        if prime[n] or prime[m]:
            return -1
        dist = [float('inf')] * limit
        dist[n] = n
        heap = [(n, n)]
        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            place = 1
            while place < limit:
                digit = x // place % 10
                if digit < 9:
                    y = x + place
                    new = cost + y
                    if not prime[y] and new < dist[y]:
                        dist[y] = new
                        heapq.heappush(heap, (new, y))
                if digit > 0:
                    y = x - place
                    if y >= low and not prime[y]:
                        new = cost + y
                        if new < dist[y]:
                            dist[y] = new
                            heapq.heappush(heap, (new, y))
                place *= 10
        return -1

