from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        first = [False] * n
        answer = 0
        for i in range(1, (n - 1) // 2 + 1):
            if z[i] >= i:
                first[i] = True
                answer += n - 2 * i

        for length in range(1, (n - 1) // 2 + 1):
            run = 0
            for i in range(n - length - 1, 0, -1):
                if nums[i] == nums[i + length]:
                    run += 1
                    if run >= length and not (first[i] and length >= i):
                        answer += 1
                else:
                    run = 0
        return answer

