        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))
        inf = 10**18
        dist = [inf] * n
        dist[0] = 0
        heap = [(0, 0)]
        remaining = n
        while heap:
            cost, u = heapq.heappop(heap)
            if cost != dist[u]:
                continue
            remaining -= 1
            if remaining == 0:
                return cost
            for v, w in reverse[u]:
                candidate = max(cost, w)
                if candidate < dist[v]:
                    dist[v] = candidate
                    heapq.heappush(heap, (candidate, v))
